{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "AZD0837, a structurally related prodrug containing a proline amide and a benzyl amidoxime, has an absolute oral bioavailability of 22–55% in humans, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Perindopril, an ethyl ester prodrug with a cyclohexyl-proline-like scaffold, has an absolute oral bioavailability of about 75% in humans, supporting high F for the query's ester prodrug form.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Desethyloxybutynin, an ester-containing cyclohexyl drug, shows 62–78% oral bioavailability in healthy adults, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Vernakalant, a moderately polar ionizable drug, has absolute oral bioavailability of 71 ± 21% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Betaxolol, an aryloxypropanolamine with moderate polarity, has absolute oral bioavailability of about 82% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Perindoprilat, the active diacid metabolite of perindopril, has a lower oral bioavailability of 19% in young healthy subjects; however, this applies to the free acid metabolite rather than the ethyl ester prodrug, so it is less transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F ≥ 20%) based on multiple high-transfer human bioavailability measurements, especially AZD0837 (amidoxime/proline prodrug, F 22–55%) and perindopril (ethyl ester prodrug, F ~75%). The only low value (perindoprilat, 19%) is for the active acid metabolite, not the ester prodrug, and is outweighed by the prodrug-relevant analogues.",
  "evidence_gaps": [
    "No direct human bioavailability data for the exact query molecule.",
    "The query's high TPSA (146 Å²) and HBD/HBA counts may reduce passive permeability; the extent to which the ethyl ester and amidoxime promoieties improve absorption is inferred from analogues, not measured for this exact compound.",
    "First-pass hydrolysis/amidoxime reduction and systemic conversion of the prodrug are not directly quantified for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

